import pandas as pd
invoices = pd.read_csv('/app/dataset/invoices.csv')

# Find all blocks of identical sellers or buyers of length >= 3
print('Checking contiguous seller blocks >= 3 in rows 240+:')
s_blocks = []
curr_s, count = None, 0
for idx, s in enumerate(invoices['seller_id'].iloc[240:], start=240):
    if s == curr_s:
        count += 1
    else:
        if count >= 3:
            s_blocks.append((curr_s, count, idx - count, idx - 1))
        curr_s = s
        count = 1
if count >= 3:
    s_blocks.append((curr_s, count, len(invoices) - count, len(invoices) - 1))
print('Seller blocks >= 3:', s_blocks)

print('Checking contiguous buyer blocks >= 3 in rows 240+:')
b_blocks = []
curr_b, count = None, 0
for idx, b in enumerate(invoices['buyer_id'].iloc[240:], start=240):
    if b == curr_b:
        count += 1
    else:
        if count >= 3:
            b_blocks.append((curr_b, count, idx - count, idx - 1))
        curr_b = b
        count = 1
if count >= 3:
    b_blocks.append((curr_b, count, len(invoices) - count, len(invoices) - 1))
print('Buyer blocks >= 3:', b_blocks)
"

