import pandas as pd
invoices = pd.read_csv('/app/dataset/invoices.csv')

def get_first_digit(val):
    s = f'{val:.2f}'.lstrip('0').replace('.', '')
    for char in s:
        if char in '123456789':
            return int(char)
    return None

for s in [3915, 4691, 6703, 7951]:
    sub = invoices[invoices['seller_id'] == s]
    d = sub['net_amount'].apply(get_first_digit).value_counts().to_dict()
    print(f'Seller {s}: {d}')
